    private static function hash(array $v):string{return hash('sha256',json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));}
    private function tx(callable $fn,bool $read=false):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL '.($read?'REPEATABLE READ':'READ COMMITTED'));$this->db->beginTransaction();try{if(!$read&&!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1]??null)===1062)throw new HttpError(409,'Mã yêu cầu hoặc giao dịch đã được ghi nhận.');throw $e;}}
    private static function input(array $in):array
