    }
    public function create(array $body):array
    {
        $in=self::input($body);$hash=self::hash(['input'=>$in,'context'=>['channel'=>'WEB']]);return $this->tx(function()use($in,$hash){$prior=$this->query('SELECT code,request_hash FROM jingo_carts WHERE request_id=?',[$in['requestId']])->fetch(PDO::FETCH_ASSOC);if($prior){if(!hash_equals($prior['request_hash'],$hash))throw new HttpError(409,'Mã yêu cầu giỏ đã dùng với nội dung khác.');return ['code'=>$prior['code'],'accessKey'=>$in['accessKey']];}$id=self::uid();$code='JC'.strtoupper(bin2hex(random_bytes(5)));$secret=(new SecretCipher(OrderMail::directory()))->encrypt($in['accessKey']);$this->query("INSERT INTO jingo_carts(id,code,request_id,request_hash,channel,partner_id,counter_id,access_hash,secret,total) VALUES (?,?,?,?,'WEB',NULL,NULL,?,?,?)",[$id,$code,$in['requestId'],$hash,hash('sha256',$in['accessKey']),$secret,$in['total']]);$anchor=null;$orders=new Orders($this->db);foreach($in['items'] as $position=>$item){$created=$orders->create($item+['requestId'=>self::uid(),'accessKey'=>$in['accessKey'],'contact'=>$in['contact'],'accepted'=>true,'locale'=>$in['locale']],null,null,true);$order=$this->query('SELECT id FROM jingo_orders WHERE code=?',[$created['code']])->fetchColumn();$anchor??=$order;$this->query('INSERT INTO jingo_cart_orders(cart_id,order_id,position) VALUES (?,?,?)',[$id,$order,$position]);}OrderMail::enqueue($this->db,$anchor,'CART_CREATED',1);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),'customer','cart.create',$id]);(new Notifications($this->db))->enqueue('TICKET',$code);return ['code'=>$code,'accessKey'=>$in['accessKey']];});
    }
    private function members(string $id,bool $lock=false):array{return $this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY '.($lock?'o.id':'m.position').($lock?' FOR UPDATE':''),[$id])->fetchAll(PDO::FETCH_ASSOC);}
    public function lookup(array $in):array
