        $cart=$this->query('SELECT * FROM jingo_carts WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart)throw new HttpError(404,'Không tìm thấy giỏ vé.');if($cart['channel']!=='WEB')throw new HttpError(409,'Chưa chuyển luồng giỏ POS/CTV.');$rows=$this->members($cart['id']);if(!$rows)throw new HttpError(409,'Giỏ thiếu đơn con. Cần đối chiếu dữ liệu.');$key=null;if($proof){$contact=json_decode($rows[0]['contact'],true,512,JSON_THROW_ON_ERROR);$ok=isset($proof['accessKey'])?hash_equals($cart['access_hash'],hash('sha256',$proof['accessKey'])):strcasecmp(trim($contact['email']),trim($proof['email']))===0;if(!$ok)throw new HttpError(404,'Không tìm thấy giỏ vé.');$key=(new SecretCipher(OrderMail::directory()))->decrypt($cart['secret']);if(!hash_equals($cart['access_hash'],hash('sha256',$key)))throw new HttpError(503,'Khóa giỏ không khớp.');}$items=[];$active=[];$orders=new Orders($this->db);foreach($rows as $row){$item=$proof?$orders->lookup(['code'=>$row['code'],'accessKey'=>$key]):$orders->get($row['id']);$item['id']=$row['id'];$item['archived']=(bool)$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$row['id']])->fetchColumn();if($proof&&($item['archived']||$item['bookingStatus']!=='CONFIRMED'||!in_array($item['paymentStatus'],['PAID','CREDIT'],true)))$item['tickets']=[];if($proof&&!$item['archived']&&$item['bookingStatus']==='CONFIRMED')$item['accessKey']=$key;if(!$item['archived']&&$item['bookingStatus']==='CONFIRMED')$active[]=$item;$items[]=$item;}$payable=array_sum(array_map(fn($i)=>$i['paymentStatus']==='UNPAID'?$i['snapshot']['total']:0,$active));return ['code'=>$code,'channel'=>$cart['channel'],'version'=>(int)$cart['version'],'total'=>(int)$cart['total'],'payable'=>$payable,'settled'=>count($active)>0&&count(array_filter($active,fn($i)=>$i['paymentStatus']==='UNPAID'))===0,'items'=>$items,'onlinePaymentEligible'=>false];
    }
    public function pay(string $code,array $in,string $actor):array
    {
        $code=self::code($code);if(array_diff(array_keys($in),['requestId','action','expectedTotal','method','reference'])||($in['action']??null)!=='PAY'||!is_int($in['expectedTotal']??null)||$in['expectedTotal']<0||$in['expectedTotal']>15000000000||!in_array($in['method']??null,['CASH','BANK'],true))self::bad('Kiểm tra khoản thu chung giỏ.');$in['requestId']=self::uuid($in['requestId']??null);$ref=$in['reference']??'';if(!is_string($ref)||strlen(mb_convert_encoding($ref,'UTF-16LE','UTF-8'))/2>150||preg_match('/[\x00-\x1f\x7f]/u',$ref))self::bad();$in['reference']=mb_strtoupper(trim($ref),'UTF-8');if($in['method']==='BANK'&&($in['reference']===''||str_starts_with($in['reference'],'CART_CASH:')||str_starts_with($in['reference'],'CASH:')))self::bad('Nhập tham chiếu ngân hàng hợp lệ.');$hash=self::hash(['code'=>$code,'data'=>$in,'actor'=>$actor]);$this->tx(function()use($code,$in,$hash,$actor){$cart=$this->query('SELECT * FROM jingo_carts WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart)throw new HttpError(404,'Không tìm thấy giỏ vé.');if($cart['channel']!=='WEB')throw new HttpError(409,'Chưa hỗ trợ thu giỏ POS/CTV.');$old=$this->query('SELECT request_hash FROM jingo_cart_actions WHERE id=?',[$in['requestId']])->fetchColumn();if($old!==false){if(!hash_equals($old,$hash))throw new HttpError(409,'Mã thao tác đã dùng.');return [];}$eligible=[];foreach($this->members($cart['id'],true) as $r)if($r['booking_status']==='CONFIRMED'&&$r['payment_status']==='UNPAID'&&!$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$r['id']])->fetchColumn())$eligible[]=$r;$total=array_sum(array_map(fn($r)=>json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR)['total'],$eligible));if(!$eligible||$total!==$in['expectedTotal'])throw new HttpError(409,'Số còn phải thu đã thay đổi. Tải lại giỏ.');$reference=$in['method']==='CASH'?'CART_CASH:'.$in['requestId']:$in['reference'];$refHash=hash('sha256',$reference);$this->query("INSERT INTO jingo_payment_r